* glue.s - integration of the (relocated, patched) arcade program with the Neo Geo runtime.
*
*   game_main   : entered from USER (demo/title request): sets up the I/O shadow and jumps to the
*                 arcade reset entry 0x2400 (its SSP is relocated to ARC_WRAM+0x3F80 by the patcher).
*   frame_hook  : called from our VBlank handler after SYSTEM_IO: feeds the inputs, runs the arcade
*                 VBlank handler (0x2F8C) on the runtime stack, then syncs palette/tiles/sprites.
*   mcu_frame   : in mcu.s.
*   oracle stubs: generated by tools/mkrom.py into build/stubs.s.

        .include "neogeo.i"
        .include "ram.i"

        .text
        .global game_main, sound_init, frame_hook, trap1_handler

        .equ    ARC_RESET,      0x2400
        .equ    ARC_IRQ6,       0x2F8C
        .equ    ARC_WRAM_STACK, ARC_WRAM+0x3F80

* ---- arcade input word (700002/3), active low ----
        .equ    ARC_P1_UP,      0
        .equ    ARC_P1_DOWN,    1
        .equ    ARC_P1_RIGHT,   2
        .equ    ARC_P1_LEFT,    3
        .equ    ARC_P1_GEAR,    4
        .equ    ARC_P1_ACCEL,   5
        .equ    ARC_COIN1,      6
        .equ    ARC_COIN2,      7
        .equ    ARC_START1,     14
        .equ    ARC_START2,     15

sound_init:
        rts

game_main:
        bsr     io_init
        clr.b   rt_in_game
        clr.b   rt_gear
        clr.b   rt_coin_pulse
        clr.b   rt_start_pulse
        clr.b   rt_start_req
        bsr     selftest_decrypt
        jmp     ARC_RESET

* I/O shadow defaults: DSW = 0xFFDF (MAME defaults: joystick, 2 sticks, normal, demo sounds on, 1C/1C),
* inputs idle, SYSTEM idle, wheel idle.
io_init:
        move.w  #0xFFDF,IO_DSW
        move.w  #0xFFFF,IO_P1P2
        move.w  #0x00FF,IO_WHEEL
        move.w  #0xFFF3,IO_SYSTEM
        rts

* Build the arcade input word from the Neo Geo controls (BIOS_P1CURRENT: bit0 up,1 down,2 left,3 right,
* 4 A,5 B,6 C,7 D, active high after SYSTEM_IO).  A = accelerate, B = gear toggle, C = accelerate too.
io_update:
        move.w  #0xFFFF,d0
        move.b  BIOS_P1CURRENT,d1
        btst    #0,d1
        beq.s   1f
        bclr    #ARC_P1_UP,d0
1:      btst    #1,d1
        beq.s   2f
        bclr    #ARC_P1_DOWN,d0
2:      btst    #2,d1
        beq.s   3f
        bclr    #ARC_P1_LEFT,d0
3:      btst    #3,d1
        beq.s   4f
        bclr    #ARC_P1_RIGHT,d0
4:      move.b  d1,d2
        and.b   #0x50,d2                /* A or C */
        beq.s   5f
        bclr    #ARC_P1_ACCEL,d0
5:      /* gear toggle on B press (edge) */
        move.b  d1,d2
        and.b   #0x20,d2
        move.b  rt_prev_b,d3
        move.b  d2,rt_prev_b
        tst.b   d3
        bne.s   6f
        tst.b   d2
        beq.s   6f
        eori.b  #1,rt_gear
6:      tst.b   rt_gear
        beq.s   7f
        bclr    #ARC_P1_GEAR,d0
7:      /* start: raw button or synthetic pulse */
        move.b  BIOS_STATCURNT,d1
        btst    #0,d1
        beq.s   8f
        bclr    #ARC_START1,d0
8:      tst.b   rt_start_pulse
        beq.s   9f
        subq.b  #1,rt_start_pulse
        bclr    #ARC_START1,d0
9:      /* synthetic coin after PLAYER_START (BIOS validated the credit) */
        tst.b   rt_start_req
        beq.s   10f
        clr.b   rt_start_req
        move.b  #2,rt_coin_pulse
        move.b  #20,rt_start_pulse
10:     tst.b   rt_coin_pulse
        beq.s   11f
        subq.b  #1,rt_coin_pulse
        bclr    #ARC_COIN1,d0
        bset    #ARC_START1,d0          /* coin first, start a few frames later */
11:     move.w  d0,IO_P1P2
        rts

* frame_hook: runs inside our VBlank handler (all registers saved by the caller)
frame_hook:
        bsr     io_update
        /* run the arcade IRQ handler on the runtime stack with a fake exception frame */
        move.l  sp,rt_saved_sp
        lea     RT_STACK,sp
        pea     arc_irq_done
        move    sr,-(sp)
        jmp     ARC_IRQ6
arc_irq_done:
        bsr     palette_sync
        bsr     video_frame
        move.l  rt_saved_sp,sp
        rts

* TRAP #1: dispatch an arcade VRAM write (2/4-byte instruction replaced by the trap) to its stub.
* Stack on entry: SR.w, PC.l (PC = address after the trap opcode).
        .global trap1_handler
trap1_handler:
        movem.l d0-d1/a0-a1,-(sp)
        move.l  18(sp),a0               /* return PC */
        lea     trap_table,a1
1:      move.l  (a1),d0
        beq     trap_error_pc
        cmp.l   d0,a0
        beq     2f
        lea     12(a1),a1
        bra     1b
2:      move.l  8(a1),d0
        add.l   d0,18(sp)               /* skip the padding after the trap */
        move.l  4(a1),rt_trap_stub
        movem.l (sp)+,d0-d1/a0-a1
        pea     trap1_rte
        move.l  rt_trap_stub,-(sp)
        rts                             /* -> stub, which returns to trap1_rte */
trap1_rte:
        rte
trap_error_pc:
        movem.l (sp)+,d0-d1/a0-a1
        jmp     trap_error

* palette_sync: arcade palette RAM shadow (xBRG444, entries 0..1023) -> ARC_PAL (Neo Geo format) for
* the 16-colour palettes whose raw words changed since the last call.
palette_sync:
        lea     ARC_PALRAW,a0
        lea     ARC_PALLAST,a1
        lea     ARC_PAL,a2
        lea     rt_pal_dirty,a3
        lea     pal_table,a4
        moveq   #63,d7
ps_pal:
        movem.l (a0),d0-d3
        cmp.l   (a1),d0
        bne.s   ps_conv
        cmp.l   4(a1),d1
        bne.s   ps_conv
        cmp.l   8(a1),d2
        bne.s   ps_conv
        cmp.l   12(a1),d3
        bne.s   ps_conv
        movem.l 16(a0),d0-d3
        cmp.l   16(a1),d0
        bne.s   ps_conv
        cmp.l   20(a1),d1
        bne.s   ps_conv
        cmp.l   24(a1),d2
        bne.s   ps_conv
        cmp.l   28(a1),d3
        bne.s   ps_conv
        lea     32(a0),a0
        lea     32(a1),a1
        lea     32(a2),a2
        addq.l  #1,a3
        dbra    d7,ps_pal
        rts
ps_conv:
        moveq   #15,d6
1:      move.w  (a0)+,d0
        move.w  d0,(a1)+
        and.w   #0x0FFF,d0
        add.w   d0,d0
        move.w  (a4,d0.w),(a2)+
        dbra    d6,1b
        st      (a3)+
        st      rt_pal_any
        dbra    d7,ps_pal
        rts

* selftest_decrypt: decrypt a few known pairs into rt_test_out so the MAME harness can check decrypt_long
selftest_decrypt:
        lea     test_vals(pc),a0
        lea     rt_test_out,a1
        moveq   #5,d1
1:      move.l  (a0)+,d0
        jsr     decrypt_long
        move.l  d0,(a1)+
        dbra    d1,1b
        rts
test_vals:
        .long   0x4D0FF8A6, 0x40544454, 0x095DB400, 0x4054EBE5, 0x3A3F3D18, 0xC8411F0E
        .align  2

* ------------------------------------------------------------------------------------------
* Fast replacements for the arcade routines that write whole blocks of tiles (patched at their
* entry with `jmp` by tools/mkrom.py).  Same register effects as the originals.
* ------------------------------------------------------------------------------------------
        .global blk_copy_l1, blk_copy_l0, clear_l1, clear_l0

* 0x11CF4 / 0x11D62: draw image block d0 at position d4 (row<<8 | column) into layer 1 / layer 0.
* Header (decrypted): bits 0-7 height, 8-15 width, 16-31 offset into the data region.
blk_copy_l1:
        movem.l d5-d7/a0/a3/a6,-(sp)
        lea     0xE5674,a1
        movea.l ARC_WRAM+0x2C3C,a2
        lsl.b   #2,d4
        addi.b  #0x14,d4
        addi.l  #0x102000,d4
        moveq   #1,d7                   /* clip at the end of VRAM like the original */
        bra     blk_common
blk_copy_l0:
        movem.l d5-d7/a0/a3/a6,-(sp)
        lea     0xEA1BE,a1
        movea.l ARC_WRAM+0x2C48,a2
        lsl.b   #2,d4
        addi.l  #0x100014,d4
        moveq   #0,d7
blk_common:
        lsl.w   #2,d0
        move.l  (a1,d0.w),d0
        moveq   #0,d3
        move.b  d0,d3                   /* height */
        lsr.w   #8,d0
        moveq   #0,d2
        move.b  d0,d2                   /* width */
        swap    d0
        move.w  d0,d1                   /* data offset (16-bit, sign-extended by the original addressing) */
        movea.l d4,a5
        subq.w  #1,d2
        subq.w  #1,d3
        move.w  d2,d6
blk_row:
        movea.l a5,a4
        move.w  d6,d2
blk_col:
        move.l  (a2,d1.w),d0
        addq.w  #4,d1
        movem.l d1-d2/a2,-(sp)
        movea.l a4,a0
        jsr     vram_store
        movem.l (sp)+,d1-d2/a2
        addq.l  #4,a4
        tst.w   d7
        beq     1f
        cmpa.l  #0x104000,a4
        bge     blk_done
1:      dbra    d2,blk_col
        adda.l  #0x100,a5
        tst.w   d7
        beq     2f
        cmpa.l  #0x104000,a5
        bge     blk_done
2:      dbra    d3,blk_row
blk_done:
        movem.l (sp)+,d5-d7/a0/a3/a6
        rts

* 0x11FDC / 0x11FF2: fill a layer with the empty tile pair (0xDF64C / 0xDF650, decrypted at build time)
clear_l1:
        lea     ARC_VRAM+0x2000,a0
        move.l  0xDF64C,d0
        bsr     clear_fill
        lea     rt_col_loaded+24,a0
        bra     clear_inval
clear_l0:
        lea     ARC_VRAM,a0
        move.l  0xDF650,d0
        bsr     clear_fill
        lea     rt_col_loaded,a0
clear_inval:
        moveq   #NCOLSPR-1,d0
1:      move.b  #0xFF,(a0)+             /* column sprites reload at the next frame */
        dbra    d0,1b
        rts
clear_fill:
        movem.l d1-d7,-(sp)
        move.l  d0,d1
        move.l  d0,d2
        move.l  d0,d3
        move.l  d0,d4
        move.l  d0,d5
        move.l  d0,d6
        move.l  d0,d7
        move.w  #255,d0
2:      movem.l d1-d7,(a0)
        move.l  d1,28(a0)
        lea     32(a0),a0
        dbra    d0,2b
        movem.l (sp)+,d1-d7
        rts
